function defaultQuote(value) { return JSON.stringify(value); }
/** Print every canonical filter through the same public `filter.*` authoring surface. */
export function printFilter(filter, codec) {
    const namespace = codec.namespace ?? "filter";
    const quote = codec.quote ?? defaultQuote;
    const call = (helper, args) => {
        codec.used?.(helper);
        return `${namespace}.${helper}(${args})`;
    };
    const value = (input) => printFilterValue(input, codec, call, quote);
    const left = "field" in filter && filter.field !== undefined
        ? codec.field(filter.field)
        : "leftValue" in filter && filter.leftValue !== undefined
            ? filter.leftValue.type === "FIELD" ? codec.field(filter.leftValue.value) : value(filter.leftValue)
            : "undefined /* TODO: filter has no left side */";
    const core = () => {
        switch (filter.type) {
            case "TRUE": return call("whereTrue", "");
            case "FALSE": return call("whereFalse", "");
            case "AND": return call("and", filter.children.map((child) => printFilter(child, codec)).join(", "));
            case "OR": return call("or", filter.children.map((child) => printFilter(child, codec)).join(", "));
            case "EQUALS": return call(filter.not === true ? "neq" : "eq", `${left}, ${value(filter.value)}`);
            case "GREATER_THAN": return call("gt", `${left}, ${value(filter.value)}`);
            case "GREATER_THAN_EQUALS": return call("gte", `${left}, ${value(filter.value)}`);
            case "LESS_THAN": return call("lt", `${left}, ${value(filter.value)}`);
            case "LESS_THAN_EQUALS": return call("lte", `${left}, ${value(filter.value)}`);
            case "LIKE": return call("like", `${left}, ${value(filter.value)}${printLikeOptions(filter, quote)}`);
            case "IS_NULL": return call(filter.not === true ? "isNotNull" : "isNull", left);
            case "IN": return call(filter.not === true ? "isNotIn" : "isIn", `${left}, [${filter.values.map(value).join(", ")}]`);
            case "BETWEEN": return call("between", `${left}, ${value(filter.min)}, ${value(filter.max)}${filter.not === true ? ", { not: true }" : ""}`);
            case "CONTAINS":
            case "OVERLAPS": {
                const helper = filter.type === "CONTAINS" ? "contains" : "overlaps";
                return call(helper, `${left}, [${filter.values.map(value).join(", ")}]${filter.not === true ? ", { not: true }" : ""}`);
            }
            case "CURRENT_RANGE": {
                const options = [`unit: ${quote(filter.unit)}`];
                if (filter.semantic !== undefined)
                    options.push(`semantic: ${filter.semantic}`);
                if (filter.isoWeek !== undefined)
                    options.push(`isoWeek: ${filter.isoWeek}`);
                return call("currentRange", `${left}, { ${options.join(", ")} }`);
            }
            case "CONSECUTIVE_RANGE": {
                const options = [`unit: ${quote(filter.unit)}`, `count: ${filter.count}`, `offset: ${filter.offset}`];
                if (filter.semantic !== undefined)
                    options.push(`semantic: ${filter.semantic}`);
                if (filter.isoWeek !== undefined)
                    options.push(`isoWeek: ${filter.isoWeek}`);
                return call("consecutiveRange", `${left}, { ${options.join(", ")} }`);
            }
        }
    };
    const printed = core();
    if (filter.type === "TRUE" || filter.type === "FALSE" || filter.type === "AND" || filter.type === "OR")
        return printed;
    const options = [
        ...(filter.aspect !== undefined ? [`aspect: ${(codec.aspect ?? codec.field)(filter.aspect)}`] : []),
        ...(filter.type !== "CURRENT_RANGE" && filter.type !== "CONSECUTIVE_RANGE" && filter.semantic === true
            ? ["semantic: true"]
            : []),
    ];
    return options.length === 0 ? printed : call("withOptions", `${printed}, { ${options.join(", ")} }`);
}
function printLikeOptions(filter, quote) {
    const options = [];
    if (filter.not === true)
        options.push("not: true");
    if (filter.caseInsensitive !== undefined)
        options.push(`caseInsensitive: ${filter.caseInsensitive}`);
    if (filter.mode !== undefined && filter.mode !== "LEGACY")
        options.push(`mode: ${quote(filter.mode.toLowerCase())}`);
    return options.length === 0 ? "" : `, { ${options.join(", ")} }`;
}
function printFilterValue(value, codec, call, quote) {
    switch (value.type) {
        case "TEXT":
        case "UUID":
        case "DATE":
        case "DATETIME": return quote(value.value);
        case "NUMBER":
        case "BOOLEAN": return String(value.value);
        case "NULL": return "null";
        case "FIELD": {
            if (value.aspect === undefined && value.treatNullAsEquals === undefined)
                return codec.field(value.value);
            const options = [
                ...(value.aspect !== undefined ? [`aspect: ${quote(value.aspect)}`] : []),
                ...(value.treatNullAsEquals !== undefined ? [`treatNullAsEquals: ${value.treatNullAsEquals}`] : []),
            ];
            return call("fieldValue", `${codec.field(value.value)}, { ${options.join(", ")} }`);
        }
        case "CURRENT_USER": return call("currentUser", quote(value.valueType ?? "ID"));
        case "REFERENCE": {
            const options = value.multiple === true ? ", { multiple: true }" : "";
            let helper;
            switch (value.realType) {
                case "BOOLEAN":
                    helper = "boolean";
                    break;
                case "DATE":
                    helper = "date";
                    break;
                case "DATETIME":
                    helper = "dateTime";
                    break;
                case "NUMBER":
                    helper = "number";
                    break;
                case "TEXT":
                    helper = "text";
                    break;
                case "UUID":
                    helper = "uuid";
                    break;
                default: throw new Error(`unsupported filter reference type "${value.realType}"`);
            }
            return call(helper, `${codec.reference(value.value)}${options}`);
        }
        case "RECORD_FIELD": return `${JSON.stringify(value)} as const`;
    }
}
